import {blankHuman,validateHuman,validateRecord,reviseRecord,recordFields,gates,gateStates,storySignals,recordStatus,reviewSummary,humanReport} from './human-core.js';
import {blankWorkspace,validateWorkspace} from './testing-core.js';
const $=id=>document.getElementById(id),key='rr-human-testing-v1';let h=blankHuman(),w=blankWorkspace(),editing='',pending=null,storedOK=true;
const status=t=>$('human-status').textContent=t;
try{const raw=localStorage.getItem(key);if(raw)h=validateHuman(JSON.parse(raw));}catch{storedOK=false;status('Saved HIST data could not be read. Export the stored data before replacing it. Saving is disabled until valid data is imported.');}
function readWork(){try{const raw=localStorage.getItem('rr-testing-workspace-v1');w=raw?validateWorkspace(JSON.parse(raw)):blankWorkspace();}catch{w=blankWorkspace();status('Workbench data could not be read. Open the workbench to recover it; no story evidence is assumed.');}}
function persist(next){if(!storedOK)throw Error('Recover or import valid HIST data before saving.');try{localStorage.setItem(key,JSON.stringify(next));}catch{throw Error('Browser storage is unavailable or full. Export your work before leaving.');}h=next;}
function download(name,data,type){const url=URL.createObjectURL(new Blob([data],{type})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
const guard=fn=>async e=>{e?.preventDefault();try{await fn();}catch(err){status(err.message);}};
function storySelect(){const selected=$('hist-story').value;$('hist-story').replaceChildren(new Option('Standalone investigation',''));for(const s of w.stories)$('hist-story').append(new Option(s.title+' · r'+s.revision,s.id));if(w.stories.some(s=>s.id===selected))$('hist-story').value=selected;}
function records(){const host=$('hist-records');host.replaceChildren();$('hist-count').textContent=String(h.records.length);if(!h.records.length){const p=document.createElement('p');p.className='human-empty';p.textContent='No investigations yet. Start with a question worth asking.';host.append(p);}for(const r of [...h.records].reverse()){const el=document.createElement('article');el.className='human-record';const title=document.createElement('h3'),meta=document.createElement('small'),p=document.createElement('p'),b=document.createElement('button');title.textContent=r.title;meta.textContent=`${r.state} · ${recordStatus(r,w)}`;if(meta.textContent.includes('changed')||meta.textContent.includes('no longer'))meta.className='warning';p.textContent=r.hypothesis;b.type='button';b.textContent='Open investigation';b.onclick=()=>{editing=r.id;for(const k of recordFields)$('hist-'+k).value=r[k];$('hist-state').value=r.state;$('hist-story').value=r.storyId;if(r.storyId&&!w.stories.some(s=>s.id===r.storyId))status('The linked story is unavailable. Saving will retain its original reference until you choose another story.');else status(`Editing ${r.title}. Saving links the investigation to the current story revision.`);location.hash='hist';$('hist-title').focus();};el.append(title,meta,p,b);host.append(el);}}
$('human-form').onsubmit=guard(()=>{readWork();const next=structuredClone(h),old=h.records.find(r=>r.id===editing),selected=$('hist-story').value,story=w.stories.find(s=>s.id===selected);let storyId=selected,storyRevision=story?.revision||0;if(old?.storyId&&!selected&&!w.stories.some(s=>s.id===old.storyId)){storyId=old.storyId;storyRevision=old.storyRevision;}
const r=reviseRecord(old,{id:editing||crypto.randomUUID(),at:new Date().toISOString(),storyId,storyRevision,state:$('hist-state').value,...Object.fromEntries(recordFields.map(k=>[k,$('hist-'+k).value.trim()]))});validateRecord(r);if(old)next.records[next.records.findIndex(x=>x.id===editing)]=r;else{if(next.records.length>=200)throw Error('Limit: 200 investigations. Export this workspace before starting another.');next.records.push(r);}persist(validateHuman(next));editing=r.id;records();$('hist-state').value=r.state;$('hist-reviewer').value=r.reviewer;$('hist-conclusion').value=r.conclusion;status(old?.state==='Reviewed'&&r.state==='Investigating'?'Investigation context changed. Previous review cleared; review the revised evidence again.':'Investigation saved. Notes are user-recorded evidence, not automatically verified results.');});
$('hist-new').onclick=()=>{editing='';$('human-form').reset();$('hist-title').focus();status('New investigation. Previously saved records are retained.');};
const prompts=[['People & consequences','Who could be harmed or excluded even when the acceptance checks pass?'],['Challenge the model','Which assumption am I treating as fact, and what observation would disprove it?'],['Change the conditions','What happens with different timing, roles, data, interruptions or recovery?'],['Question the oracle','Why do I believe this behavior is correct? What would challenge that judgment?'],['Look beyond the happy path','Can a person understand, recover from and trust an unexpected outcome?']];for(const [name,prompt]of prompts){const b=document.createElement('button');b.type='button';const strong=document.createElement('b');strong.textContent=name;b.append(strong,document.createTextNode(prompt));b.onclick=()=>{const field=$('hist-hypothesis');field.value=(field.value.trim()?field.value.trim()+'\n\n':'')+prompt;field.focus();status('Thinking prompt added. Investigate it before recording any conclusion.');};$('thinking-cards').append(b);}
function agile(){const signals=storySignals(w),missing=signals.filter(s=>s.flags.length).length;const metrics=$('agile-metrics');metrics.replaceChildren();for(const [value,label]of [[w.stories.length,'Sprint stories'],[signals.filter(s=>s.observedSessions).length,'Stories with observations'],[missing,'Stories with open prompts']]){const d=document.createElement('div'),n=document.createElement('strong'),l=document.createElement('span');n.textContent=String(value);l.textContent=label;d.append(n,l);metrics.append(d);}$('agile-context').textContent=`${w.sprint.name} · ${w.sprint.goal||'No sprint goal recorded yet.'}`;const host=$('agile-stories');host.replaceChildren();if(!signals.length){const p=document.createElement('p');p.className='human-empty';p.textContent='No stories yet. Add stories in the workbench or import a Jira sprint there.';host.append(p);}for(const s of signals){const row=document.createElement('article');row.className='agile-row';const title=document.createElement('h3'),meta=document.createElement('small'),p=document.createElement('p'),flags=document.createElement('div');title.textContent=s.title;meta.textContent=`${s.status} · ${s.priority} risk priority`;p.textContent=`Revision ${s.revision} · ${s.currentSessions} sessions · ${s.observedSessions} with observations. These counts do not establish coverage.`;flags.className='agile-flags';for(const f of s.flags){const span=document.createElement('span');span.textContent=f;flags.append(span);}if(!s.flags.length){const note=document.createElement('small');note.textContent='No missing fields flagged. Review evidence quality and remaining risks with the team.';flags.append(note);}row.append(title,meta,p,flags);host.append(row);}}
$('agile-refresh').onclick=()=>{readWork();storySelect();agile();records();status('Agile evidence refreshed from this browser’s workbench.');};
for(const [id,label]of gates){const row=document.createElement('div');row.className='readiness-row';const l=document.createElement('label');l.htmlFor='gate-'+id;l.textContent=label;const select=document.createElement('select');select.id='gate-'+id;for(const s of gateStates)select.append(new Option(s,s));const input=document.createElement('input');input.id='evidence-'+id;input.maxLength=4000;input.setAttribute('aria-label',label+' evidence or rationale');input.placeholder='Evidence reference, blocker, or reason this is not applicable';row.append(l,select,input);$('readiness-gates').append(row);}
function readiness(){const summary=reviewSummary(h);$('readiness-summary').textContent=summary.message;$('readiness-counts').textContent=`${summary.evidence} areas with evidence · ${summary.open} not reviewed · ${summary.blocked} blocked. All statuses are user-reported.`;}
function fillReadiness(){$('release-name').value=h.release;$('release-build').value=h.build;for(const [id]of gates){$('gate-'+id).value=h.gates[id].state;$('evidence-'+id).value=h.gates[id].evidence;}readiness();}
$('readiness-form').onsubmit=guard(()=>{const next=structuredClone(h),release=$('release-name').value.trim(),build=$('release-build').value.trim();if(!release||!build)throw Error('Specify the release and build.');const changed=(!!h.release||!!h.build)&&(release!==h.release||build!==h.build);next.release=release;next.build=build;for(const [id]of gates)next.gates[id]={state:changed?'Not reviewed':$('gate-'+id).value,evidence:$('evidence-'+id).value.trim()};persist(validateHuman(next));fillReadiness();status(changed?'Release context changed. All review statuses reset; revisit retained evidence references.':'Release review saved. The deployment decision remains with your team.');});
$('human-export').onclick=guard(()=>{const data=storedOK?JSON.stringify(h,null,2):localStorage.getItem(key)||'';download('releaseradar-hist.json',data,'application/json');status('HIST data exported. Workbench stories need their own export.');});
const exportReport=()=>{readWork();download('releaseradar-human-testing-report.md',humanReport(h,w),'text/markdown');status('Saved investigations and review exported. Unsaved form edits are not included.');};$('human-export-report').onclick=exportReport;$('human-report-bottom').onclick=exportReport;
$('human-import').onchange=guard(async()=>{const file=$('human-import').files[0];if(!file)return;if(file.size>2000000)throw Error('Import limit is 2 MB.');pending=validateHuman(JSON.parse(await file.text()));$('human-import-description').textContent=`Replace your HIST workspace with ${pending.records.length} investigations for ${pending.release||'an unnamed release'}? Export existing work first. Workbench stories are unaffected.`;$('human-import-preview').hidden=false;$('human-import').value='';});$('human-import-confirm').onclick=guard(()=>{if(!pending)return;localStorage.setItem(key,JSON.stringify(pending));h=pending;pending=null;storedOK=true;editing='';$('human-form').reset();$('human-import-preview').hidden=true;records();fillReadiness();status('HIST workspace imported. Review story revision links against this browser’s workbench.');});$('human-import-cancel').onclick=()=>{pending=null;$('human-import-preview').hidden=true;};
function view(){const id=['hist','agile','readiness'].includes(location.hash.slice(1))?location.hash.slice(1):'hist';for(const name of ['hist','agile','readiness'])$(name).hidden=name!==id;document.querySelectorAll('.human-tabs a').forEach(a=>{if(a.hash==='#'+id)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current');});if(id==='agile'){readWork();agile();}records();}
addEventListener('hashchange',view);addEventListener('storage',e=>{if(e.key==='rr-testing-workspace-v1'){readWork();storySelect();agile();records();}});readWork();storySelect();records();fillReadiness();view();
